using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Staybnb.Data;using Staybnb.Models;using Staybnb.Services;
namespace Staybnb.Controllers;
[Authorize(Roles="Admin,SuperAdmin")]
public class AdminController(ApplicationDbContext db,UserManager<ApplicationUser> users,ActivityLogger logger,NotificationService notifications):Controller {
 public async Task<IActionResult> Index(){ViewBag.Users=await users.Users.CountAsync();ViewBag.Pending=await db.HostApplications.CountAsync(a=>a.Status==WorkflowStatus.Pending);ViewBag.ActiveProperties=await db.Properties.CountAsync(p=>p.IsActive);ViewBag.PendingBookings=await db.Bookings.CountAsync(b=>b.Status==WorkflowStatus.Pending);ViewBag.Recent=await db.ActivityLogs.Include(a=>a.User).OrderByDescending(a=>a.CreatedAt).Take(12).ToListAsync();return View();}
 public async Task<IActionResult> Applications(){return View(await db.HostApplications.Include(a=>a.Applicant).Include(a=>a.Property!).ThenInclude(p=>p.Images).OrderBy(a=>a.Status).ThenBy(a=>a.AppliedAt).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ReviewApplication(int id,string decision,string? note){var a=await db.HostApplications.Include(a=>a.Property).FirstOrDefaultAsync(a=>a.Id==id);if(a==null)return NotFound();if(a.Status!=WorkflowStatus.Pending)return BadRequest("Application has already been reviewed.");if(decision is not ("approve" or "reject"))return BadRequest();var user=await users.FindByIdAsync(a.ApplicationUserId);if(user==null)return NotFound();await using var tx=await db.Database.BeginTransactionAsync();if(decision=="approve"){var add=await users.AddToRoleAsync(user,"Host");if(!add.Succeeded)return BadRequest(string.Join(";",add.Errors.Select(e=>e.Description)));if(await users.IsInRoleAsync(user,"Guest")){var remove=await users.RemoveFromRoleAsync(user,"Guest");if(!remove.Succeeded)return BadRequest(string.Join(";",remove.Errors.Select(e=>e.Description)));}a.Status=WorkflowStatus.Approved;if(a.Property!=null)a.Property.IsActive=true;}else{a.Status=WorkflowStatus.Rejected;if(a.Property!=null)a.Property.IsActive=false;}a.ReviewedAt=DateTime.UtcNow;a.ReviewedById=users.GetUserId(User);a.ReviewNote=note;await db.SaveChangesAsync();await tx.CommitAsync();var adminId=users.GetUserId(User)!;await logger.LogAsync(adminId,$"{decision}d Host application #{id}","HostApplication",$"Applicant={user.Id}");await notifications.AddAsync(user.Id,$"Your Host application was {a.Status}","HostApplication","/HostApplications/MyApplication");return RedirectToAction(nameof(Applications));}
 [Authorize(Roles="SuperAdmin")] public async Task<IActionResult> PromoteGuests(){var guestIds=await users.GetUsersInRoleAsync("Guest");return View(guestIds.Select(u=>u).ToList());}
 [Authorize(Roles="SuperAdmin"),HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> PromoteGuest(string userId){var target=await users.FindByIdAsync(userId);if(target==null)return NotFound();if(await users.IsInRoleAsync(target,"SuperAdmin"))return BadRequest();if(await users.IsInRoleAsync(target,"Host"))return BadRequest("Hosts must not also be Guests or Admins.");if(!await users.IsInRoleAsync(target,"Guest"))return BadRequest("Only Guests can be promoted.");var add=await users.AddToRoleAsync(target,"Admin");if(!add.Succeeded)return BadRequest();await users.RemoveFromRoleAsync(target,"Guest");var adminId=users.GetUserId(User)!;await logger.LogAsync(adminId,"Promoted user to Admin","RoleChange",$"TargetUser={target.Id}");await notifications.AddAsync(target.Id,"Your account role has been updated","RoleChange");return RedirectToAction(nameof(PromoteGuests));}
 public async Task<IActionResult> Activity(){return View(await db.ActivityLogs.Include(a=>a.User).OrderByDescending(a=>a.CreatedAt).Take(500).ToListAsync());}
 public async Task<IActionResult> Documents(){return View(await db.GuestDocuments.Include(d=>d.GuestCheckin!).ThenInclude(c=>c.Booking!).ThenInclude(b=>b.Property).Include(d=>d.GuestCheckin!).ThenInclude(c=>c.Booking!).ThenInclude(b=>b.Guest).OrderBy(d=>d.Status).ToListAsync());}
}
